#!/usr/bin/env python3
# -*- coding: utf-8 -*-

# Author: Rensc
# Date: 2026-08-09
# Version: dev001
# Function: Compare SeRP peak intervals between two biological conditions.
# Input: Two SeRP peak tables generated by serp_peak.
# Output: Overlap summaries, shared peak clusters, relationships, and condition-specific peaks.

"""Peak-overlap analysis for selective ribosome profiling experiments."""

from __future__ import annotations

from collections import defaultdict, deque
from pathlib import Path
import re

import numpy as np
import pandas as pd


class PeakOverlapAnalyzer:
    """Compare SeRP peak intervals between two biological conditions.

    Parameters
    ----------
    peak_a_file : str
        Peak table for condition A.
    peak_b_file : str
        Peak table for condition B.
    name_a : str
        Display name for condition A.
    name_b : str
        Display name for condition B.
    output_prefix : str
        Prefix used for all output files.
    min_overlap : int
        Minimum inclusive overlap length in codon positions.
    min_reciprocal : float
        Minimum reciprocal overlap required for both intervals.
    interval_mode : {"core", "extended"}
        Core uses ``peak_start``/``peak_end``. Extended uses
        ``collision_start``/``collision_end``.
    max_fdr : float or None
        Optional maximum BHFDR. When None, all called peaks are retained.

    Notes
    -----
    Peak matching is transcript-specific because SeRP peak coordinates are
    transcript-relative codon positions. Valid overlaps form edges in a
    bipartite interval graph. Connected components of valid edges define
    shared peak clusters and therefore retain 1:1, 1:N, N:1, and N:N
    relationships without forcing one-to-one matching.
    """

    REQUIRED_CORE_COLUMNS = {"transcripts", "peak_start", "peak_end"}
    REQUIRED_EXTENDED_COLUMNS = {"collision_start", "collision_end"}
    CLUSTER_COLUMNS = [
        "cluster_id",
        "transcripts",
        "gene_name_a",
        "gene_name_b",
        "relationship_type",
        "peak_count_a",
        "peak_count_b",
        "peak_ids_a",
        "peak_ids_b",
        "start_a",
        "end_a",
        "start_b",
        "end_b",
        "cluster_start",
        "cluster_end",
        "qualifying_relationships",
        "max_overlap_length",
        "mean_overlap_length",
        "max_reciprocal_overlap",
        "mean_reciprocal_overlap",
        "max_jaccard",
        "mean_jaccard",
    ]

    def __init__(
        self,
        peak_a_file: str,
        peak_b_file: str,
        name_a: str,
        name_b: str,
        output_prefix: str,
        min_overlap: int = 6,
        min_reciprocal: float = 0.5,
        interval_mode: str = "core",
        max_fdr: float | None = None,
    ) -> None:
        """Initialize the peak-overlap workflow."""
        self.peak_a_file = str(peak_a_file)
        self.peak_b_file = str(peak_b_file)
        self.name_a = str(name_a)
        self.name_b = str(name_b)
        self.output_prefix = str(output_prefix)
        self.min_overlap = int(min_overlap)
        self.min_reciprocal = float(min_reciprocal)
        self.interval_mode = str(interval_mode)
        self.max_fdr = max_fdr

        self.file_label_a = self._sanitize_label(self.name_a)
        self.file_label_b = self._sanitize_label(self.name_b)
        if self.file_label_a == self.file_label_b:
            raise ValueError(
                "Condition labels produce the same filename-safe label: {label}.".format(
                    label=self.file_label_a
                )
            )

        self.peak_a = pd.DataFrame()
        self.peak_b = pd.DataFrame()
        self.relationships = pd.DataFrame()
        self.shared_clusters = pd.DataFrame()
        self.annotated_a = pd.DataFrame()
        self.annotated_b = pd.DataFrame()
        self.shared_peaks = pd.DataFrame()
        self.specific_a = pd.DataFrame()
        self.specific_b = pd.DataFrame()

        self.qc_a: dict[str, int | float | str] = {}
        self.qc_b: dict[str, int | float | str] = {}

        self._adjacency: dict[str, set[str]] = defaultdict(set)
        self._cluster_by_node: dict[str, str] = {}

    @staticmethod
    def _sanitize_label(label: str) -> str:
        """Convert a condition name to a stable filename-safe label."""
        cleaned = re.sub(r"[^A-Za-z0-9._-]+", "_", label.strip())
        cleaned = cleaned.strip("._-")
        return cleaned if cleaned else "sample"

    @staticmethod
    def _safe_numeric(series: pd.Series) -> pd.Series:
        """Convert one Series to numeric values with invalid values as NaN."""
        return pd.to_numeric(series.replace("-", pd.NA), errors="coerce")

    def _read_peak_table(
        self,
        file_name: str,
        sample_name: str,
        side: str,
    ) -> tuple[pd.DataFrame, dict[str, int | float | str]]:
        """Read, validate, and normalize one SeRP peak table.

        Parameters
        ----------
        file_name : str
            Input peak table path.
        sample_name : str
            Biological condition label.
        side : {"A", "B"}
            Internal graph side identifier.

        Returns
        -------
        tuple[pandas.DataFrame, dict]
            Normalized called peaks and import/QC counts.
        """
        table = pd.read_csv(file_name, sep="\t", low_memory=False)
        table.columns = [str(column).strip() for column in table.columns]

        missing = self.REQUIRED_CORE_COLUMNS.difference(table.columns)
        if missing:
            raise ValueError(
                "Peak table {file_name} is missing required columns: {columns}".format(
                    file_name=file_name,
                    columns=", ".join(sorted(missing)),
                )
            )

        if self.interval_mode == "extended":
            missing_extended = self.REQUIRED_EXTENDED_COLUMNS.difference(table.columns)
            if missing_extended:
                raise ValueError(
                    "Extended interval mode requires columns: {columns}".format(
                        columns=", ".join(sorted(missing_extended))
                    )
                )

        qc: dict[str, int | float | str] = {
            "input_rows": int(len(table)),
            "non_peak_rows_removed": 0,
            "fdr_filtered_rows": 0,
            "fdr_missing_rows": 0,
            "called_peaks": 0,
        }

        table = table.copy()
        table["_source_row"] = np.arange(1, len(table) + 1, dtype=int)

        peak_start = self._safe_numeric(table["peak_start"])
        peak_end = self._safe_numeric(table["peak_end"])

        if "peak_num" in table.columns:
            peak_num = self._safe_numeric(table["peak_num"])
            called_mask = peak_num.gt(0) & peak_start.notna() & peak_end.notna()
            qc["non_peak_rows_removed"] = int((~called_mask).sum())
            table = table.loc[called_mask].copy()
        else:
            called_mask = peak_start.notna() & peak_end.notna()
            invalid_coordinate_rows = int((~called_mask).sum())
            if invalid_coordinate_rows:
                raise ValueError(
                    "Peak table {file_name} contains {count} rows without numeric "
                    "peak_start/peak_end and has no peak_num column to identify "
                    "non-peak status rows.".format(
                        file_name=file_name,
                        count=invalid_coordinate_rows,
                    )
                )
            table = table.loc[called_mask].copy()

        numeric_fdr = None
        if "BHFDR" in table.columns:
            numeric_fdr = self._safe_numeric(table["BHFDR"])
            qc["fdr_missing_rows"] = int(numeric_fdr.isna().sum())

        if self.max_fdr is not None:
            if numeric_fdr is None:
                raise ValueError(
                    "--max-fdr requires a BHFDR column in {file_name}.".format(
                        file_name=file_name
                    )
                )
            keep_fdr = numeric_fdr.notna() & numeric_fdr.le(float(self.max_fdr))
            qc["fdr_filtered_rows"] = int((~keep_fdr).sum())
            table = table.loc[keep_fdr].copy()

        if table.empty:
            table = self._add_empty_internal_columns(table, sample_name, side)
            qc["called_peaks"] = 0
            return table, qc

        core_start = self._safe_numeric(table["peak_start"])
        core_end = self._safe_numeric(table["peak_end"])
        if core_start.isna().any() or core_end.isna().any():
            raise ValueError(
                "Called peaks in {file_name} contain non-numeric peak coordinates.".format(
                    file_name=file_name
                )
            )

        core_start = core_start.astype(int)
        core_end = core_end.astype(int)
        invalid_core = core_start.gt(core_end)
        if invalid_core.any():
            examples = table.loc[invalid_core, ["transcripts", "peak_start", "peak_end"]]
            raise ValueError(
                "Peak table {file_name} contains peak_start > peak_end. Examples:\n{examples}".format(
                    file_name=file_name,
                    examples=examples.head(5).to_string(index=False),
                )
            )

        duplicate_mask = pd.DataFrame(
            {
                "transcripts": table["transcripts"].astype(str),
                "peak_start": core_start,
                "peak_end": core_end,
            }
        ).duplicated(keep=False)
        if duplicate_mask.any():
            examples = table.loc[
                duplicate_mask,
                ["transcripts", "peak_start", "peak_end"],
            ]
            raise ValueError(
                "Peak table {file_name} contains duplicated transcript/peak intervals. "
                "Examples:\n{examples}".format(
                    file_name=file_name,
                    examples=examples.head(5).to_string(index=False),
                )
            )

        table["_core_start"] = core_start.to_numpy()
        table["_core_end"] = core_end.to_numpy()
        table["_core_span_length"] = (
            table["_core_end"] - table["_core_start"] + 1
        ).astype(int)

        if "peak_length" in table.columns:
            core_length = self._safe_numeric(table["peak_length"])
            core_length = core_length.where(core_length.gt(0), table["_core_span_length"])
            core_length = core_length.fillna(table["_core_span_length"])
            table["_core_length"] = core_length.astype(int)
        else:
            table["_core_length"] = table["_core_span_length"]

        if self.interval_mode == "extended":
            match_start = self._safe_numeric(table["collision_start"])
            match_end = self._safe_numeric(table["collision_end"])
            if match_start.isna().any() or match_end.isna().any():
                raise ValueError(
                    "Extended interval coordinates must be numeric in {file_name}.".format(
                        file_name=file_name
                    )
                )
            table["_match_start"] = match_start.astype(int).to_numpy()
            table["_match_end"] = match_end.astype(int).to_numpy()
        else:
            table["_match_start"] = table["_core_start"]
            table["_match_end"] = table["_core_end"]

        invalid_match = table["_match_start"].gt(table["_match_end"])
        if invalid_match.any():
            raise ValueError(
                "Peak table {file_name} contains invalid comparison intervals.".format(
                    file_name=file_name
                )
            )

        table["_match_span_length"] = (
            table["_match_end"] - table["_match_start"] + 1
        ).astype(int)
        table["_sample"] = sample_name
        table["_side"] = side
        table["_peak_uid"] = [
            "{side}{index:06d}".format(side=side, index=index)
            for index in range(1, len(table) + 1)
        ]
        table["transcripts"] = table["transcripts"].astype(str)
        if "gene_name" in table.columns:
            table["gene_name"] = table["gene_name"].fillna("-").astype(str)

        qc["called_peaks"] = int(len(table))
        return table.reset_index(drop=True), qc

    @staticmethod
    def _add_empty_internal_columns(
        table: pd.DataFrame,
        sample_name: str,
        side: str,
    ) -> pd.DataFrame:
        """Attach internal columns to an empty normalized peak table."""
        empty = table.copy()
        internal_columns = {
            "_core_start": "int64",
            "_core_end": "int64",
            "_core_span_length": "int64",
            "_core_length": "int64",
            "_match_start": "int64",
            "_match_end": "int64",
            "_match_span_length": "int64",
        }
        for column, dtype in internal_columns.items():
            empty[column] = pd.Series(dtype=dtype)
        empty["_sample"] = pd.Series(dtype="object")
        empty["_side"] = pd.Series(dtype="object")
        empty["_peak_uid"] = pd.Series(dtype="object")
        return empty

    def load_peaks(self) -> None:
        """Import and normalize both peak tables."""
        self.peak_a, self.qc_a = self._read_peak_table(
            self.peak_a_file,
            self.name_a,
            "A",
        )
        self.peak_b, self.qc_b = self._read_peak_table(
            self.peak_b_file,
            self.name_b,
            "B",
        )

    @staticmethod
    def _interval_overlap(start_a: int, end_a: int, start_b: int, end_b: int) -> int:
        """Return the inclusive overlap length of two intervals."""
        return max(0, min(end_a, end_b) - max(start_a, start_b) + 1)

    @staticmethod
    def _gene_name(row: pd.Series) -> str:
        """Return a stable gene name from one peak row."""
        if "gene_name" not in row.index:
            return "-"
        value = str(row["gene_name"])
        return value if value and value != "nan" else "-"

    def _relationship_row(self, row_a: pd.Series, row_b: pd.Series) -> dict[str, object]:
        """Calculate interval-overlap metrics for one physical A/B overlap."""
        start_a = int(row_a["_match_start"])
        end_a = int(row_a["_match_end"])
        start_b = int(row_b["_match_start"])
        end_b = int(row_b["_match_end"])
        length_a = int(row_a["_match_span_length"])
        length_b = int(row_b["_match_span_length"])

        overlap_start = max(start_a, start_b)
        overlap_end = min(end_a, end_b)
        overlap_length = self._interval_overlap(start_a, end_a, start_b, end_b)
        fraction_a = overlap_length / length_a
        fraction_b = overlap_length / length_b
        reciprocal_overlap = min(fraction_a, fraction_b)
        union_length = max(end_a, end_b) - min(start_a, start_b) + 1
        jaccard = overlap_length / union_length
        center_a = (start_a + end_a) / 2.0
        center_b = (start_b + end_b) / 2.0

        if overlap_length < self.min_overlap:
            reason = "overlap_too_short"
            qualifying = False
        elif reciprocal_overlap < self.min_reciprocal:
            reason = "reciprocal_overlap_too_low"
            qualifying = False
        else:
            reason = "qualified"
            qualifying = True

        peak_num_a = row_a["peak_num"] if "peak_num" in row_a.index else "-"
        peak_num_b = row_b["peak_num"] if "peak_num" in row_b.index else "-"

        return {
            "cluster_id": "-",
            "transcripts": str(row_a["transcripts"]),
            "gene_name_a": self._gene_name(row_a),
            "gene_name_b": self._gene_name(row_b),
            "peak_uid_a": str(row_a["_peak_uid"]),
            "peak_uid_b": str(row_b["_peak_uid"]),
            "peak_num_a": peak_num_a,
            "peak_num_b": peak_num_b,
            "core_start_a": int(row_a["_core_start"]),
            "core_end_a": int(row_a["_core_end"]),
            "core_length_a": int(row_a["_core_length"]),
            "core_span_length_a": int(row_a["_core_span_length"]),
            "core_start_b": int(row_b["_core_start"]),
            "core_end_b": int(row_b["_core_end"]),
            "core_length_b": int(row_b["_core_length"]),
            "core_span_length_b": int(row_b["_core_span_length"]),
            "match_start_a": start_a,
            "match_end_a": end_a,
            "match_span_length_a": length_a,
            "match_start_b": start_b,
            "match_end_b": end_b,
            "match_span_length_b": length_b,
            "overlap_start": overlap_start,
            "overlap_end": overlap_end,
            "overlap_length": overlap_length,
            "overlap_fraction_a": fraction_a,
            "overlap_fraction_b": fraction_b,
            "reciprocal_overlap": reciprocal_overlap,
            "jaccard": jaccard,
            "center_shift_b_minus_a": center_b - center_a,
            "core_length_difference_b_minus_a": (
                int(row_b["_core_length"]) - int(row_a["_core_length"])
            ),
            "span_length_difference_b_minus_a": length_b - length_a,
            "qualifying_overlap": qualifying,
            "relationship_status": reason,
            "_node_a": "A:" + str(row_a["_peak_uid"]),
            "_node_b": "B:" + str(row_b["_peak_uid"]),
        }

    def _build_relationships(self) -> pd.DataFrame:
        """Build all physical interval relationships between the two samples."""
        relationship_rows: list[dict[str, object]] = []
        if self.peak_a.empty or self.peak_b.empty:
            return pd.DataFrame()

        b_by_transcript = {
            transcript: group
            for transcript, group in self.peak_b.groupby("transcripts", sort=False)
        }

        for transcript, group_a in self.peak_a.groupby("transcripts", sort=False):
            group_b = b_by_transcript.get(transcript)
            if group_b is None:
                continue

            for _, row_a in group_a.iterrows():
                start_a = int(row_a["_match_start"])
                end_a = int(row_a["_match_end"])
                for _, row_b in group_b.iterrows():
                    start_b = int(row_b["_match_start"])
                    end_b = int(row_b["_match_end"])
                    if start_b > end_a or start_a > end_b:
                        continue
                    relationship_rows.append(self._relationship_row(row_a, row_b))

        if not relationship_rows:
            return pd.DataFrame()
        return pd.DataFrame(relationship_rows)

    def _build_graph(self) -> None:
        """Build the bipartite graph from qualifying interval relationships."""
        self._adjacency = defaultdict(set)
        if self.relationships.empty:
            return

        qualifying = self.relationships.loc[
            self.relationships["qualifying_overlap"].astype(bool)
        ]
        for _, row in qualifying.iterrows():
            node_a = str(row["_node_a"])
            node_b = str(row["_node_b"])
            self._adjacency[node_a].add(node_b)
            self._adjacency[node_b].add(node_a)

    def _component_sort_key(self, nodes: set[str]) -> tuple[str, int, int]:
        """Build a deterministic sort key for one overlap graph component."""
        rows = []
        for node in nodes:
            side, peak_uid = node.split(":", 1)
            table = self.peak_a if side == "A" else self.peak_b
            matched = table.loc[table["_peak_uid"] == peak_uid]
            if not matched.empty:
                rows.append(matched.iloc[0])
        if not rows:
            return ("", 0, 0)
        transcript = min(str(row["transcripts"]) for row in rows)
        start = min(int(row["_match_start"]) for row in rows)
        end = max(int(row["_match_end"]) for row in rows)
        return (transcript, start, end)

    def _assign_components(self) -> list[set[str]]:
        """Find connected components and assign stable shared-cluster IDs."""
        components: list[set[str]] = []
        visited: set[str] = set()

        for node in sorted(self._adjacency):
            if node in visited:
                continue
            queue: deque[str] = deque([node])
            component: set[str] = set()
            visited.add(node)
            while queue:
                current = queue.popleft()
                component.add(current)
                for neighbor in sorted(self._adjacency[current]):
                    if neighbor not in visited:
                        visited.add(neighbor)
                        queue.append(neighbor)
            components.append(component)

        components.sort(key=self._component_sort_key)
        self._cluster_by_node = {}
        for index, component in enumerate(components, start=1):
            cluster_id = "SC{index:06d}".format(index=index)
            for node in component:
                self._cluster_by_node[node] = cluster_id

        if not self.relationships.empty:
            cluster_ids = []
            for _, row in self.relationships.iterrows():
                if not bool(row["qualifying_overlap"]):
                    cluster_ids.append("-")
                    continue
                cluster_ids.append(self._cluster_by_node.get(str(row["_node_a"]), "-"))
            self.relationships["cluster_id"] = cluster_ids

        return components

    @staticmethod
    def _unique_join(values: pd.Series) -> str:
        """Join unique non-empty values in stable order."""
        result = []
        seen = set()
        for value in values.astype(str):
            if value in {"", "nan", "None"}:
                continue
            if value not in seen:
                seen.add(value)
                result.append(value)
        return ",".join(result) if result else "-"

    def _build_cluster_table(self, components: list[set[str]]) -> pd.DataFrame:
        """Summarize connected components of qualifying overlap relationships."""
        cluster_rows: list[dict[str, object]] = []
        if not components:
            return pd.DataFrame(columns=self.CLUSTER_COLUMNS)

        index_a = self.peak_a.set_index("_peak_uid", drop=False)
        index_b = self.peak_b.set_index("_peak_uid", drop=False)

        for component in components:
            cluster_id = self._cluster_by_node[next(iter(component))]
            nodes_a = sorted(node.split(":", 1)[1] for node in component if node.startswith("A:"))
            nodes_b = sorted(node.split(":", 1)[1] for node in component if node.startswith("B:"))
            rows_a = index_a.loc[nodes_a]
            rows_b = index_b.loc[nodes_b]
            if isinstance(rows_a, pd.Series):
                rows_a = rows_a.to_frame().T
            if isinstance(rows_b, pd.Series):
                rows_b = rows_b.to_frame().T

            relationship_type = "{a}:{b}".format(a=len(nodes_a), b=len(nodes_b))
            edge_rows = self.relationships.loc[
                (self.relationships["cluster_id"] == cluster_id)
                & self.relationships["qualifying_overlap"].astype(bool)
            ]

            transcript_values = pd.concat(
                [rows_a["transcripts"], rows_b["transcripts"]],
                ignore_index=True,
            )
            gene_a = (
                self._unique_join(rows_a["gene_name"])
                if "gene_name" in rows_a.columns
                else "-"
            )
            gene_b = (
                self._unique_join(rows_b["gene_name"])
                if "gene_name" in rows_b.columns
                else "-"
            )

            cluster_rows.append(
                {
                    "cluster_id": cluster_id,
                    "transcripts": self._unique_join(transcript_values),
                    "gene_name_a": gene_a,
                    "gene_name_b": gene_b,
                    "relationship_type": relationship_type,
                    "peak_count_a": len(nodes_a),
                    "peak_count_b": len(nodes_b),
                    "peak_ids_a": ",".join(nodes_a),
                    "peak_ids_b": ",".join(nodes_b),
                    "start_a": int(rows_a["_match_start"].min()),
                    "end_a": int(rows_a["_match_end"].max()),
                    "start_b": int(rows_b["_match_start"].min()),
                    "end_b": int(rows_b["_match_end"].max()),
                    "cluster_start": int(
                        min(rows_a["_match_start"].min(), rows_b["_match_start"].min())
                    ),
                    "cluster_end": int(
                        max(rows_a["_match_end"].max(), rows_b["_match_end"].max())
                    ),
                    "qualifying_relationships": int(len(edge_rows)),
                    "max_overlap_length": int(edge_rows["overlap_length"].max()),
                    "mean_overlap_length": float(edge_rows["overlap_length"].mean()),
                    "max_reciprocal_overlap": float(edge_rows["reciprocal_overlap"].max()),
                    "mean_reciprocal_overlap": float(edge_rows["reciprocal_overlap"].mean()),
                    "max_jaccard": float(edge_rows["jaccard"].max()),
                    "mean_jaccard": float(edge_rows["jaccard"].mean()),
                }
            )

        return pd.DataFrame(cluster_rows, columns=self.CLUSTER_COLUMNS)

    def _annotate_peaks(self, table: pd.DataFrame, side: str) -> pd.DataFrame:
        """Annotate each peak as shared or condition-specific."""
        annotated = table.copy()
        cluster_ids = []
        partner_counts = []
        status = []

        for peak_uid in annotated["_peak_uid"]:
            node = side + ":" + str(peak_uid)
            cluster_id = self._cluster_by_node.get(node, "-")
            cluster_ids.append(cluster_id)
            partner_count = len(self._adjacency.get(node, set()))
            partner_counts.append(partner_count)
            status.append("shared" if partner_count > 0 else "specific")

        annotated["overlap_status"] = status
        annotated["shared_cluster_id"] = cluster_ids
        annotated["overlap_partner_count"] = partner_counts
        annotated["comparison_sample"] = annotated["_sample"]
        annotated["peak_uid"] = annotated["_peak_uid"]
        annotated["core_span_length"] = annotated["_core_span_length"]
        annotated["core_length_used"] = annotated["_core_length"]
        annotated["match_start"] = annotated["_match_start"]
        annotated["match_end"] = annotated["_match_end"]
        annotated["match_span_length"] = annotated["_match_span_length"]
        return annotated

    @staticmethod
    def _public_columns(table: pd.DataFrame) -> pd.DataFrame:
        """Remove private workflow columns before writing a table."""
        private_columns = [column for column in table.columns if column.startswith("_")]
        return table.drop(columns=private_columns, errors="ignore")

    def analyze(self) -> None:
        """Calculate overlap relationships, graph clusters, and peak classes."""
        self.relationships = self._build_relationships()
        if self.relationships.empty:
            self.relationships = pd.DataFrame(
                columns=[
                    "cluster_id",
                    "transcripts",
                    "gene_name_a",
                    "gene_name_b",
                    "peak_uid_a",
                    "peak_uid_b",
                    "peak_num_a",
                    "peak_num_b",
                    "core_start_a",
                    "core_end_a",
                    "core_length_a",
                    "core_span_length_a",
                    "core_start_b",
                    "core_end_b",
                    "core_length_b",
                    "core_span_length_b",
                    "match_start_a",
                    "match_end_a",
                    "match_span_length_a",
                    "match_start_b",
                    "match_end_b",
                    "match_span_length_b",
                    "overlap_start",
                    "overlap_end",
                    "overlap_length",
                    "overlap_fraction_a",
                    "overlap_fraction_b",
                    "reciprocal_overlap",
                    "jaccard",
                    "center_shift_b_minus_a",
                    "core_length_difference_b_minus_a",
                    "span_length_difference_b_minus_a",
                    "qualifying_overlap",
                    "relationship_status",
                    "_node_a",
                    "_node_b",
                ]
            )

        self._build_graph()
        components = self._assign_components()
        self.shared_clusters = self._build_cluster_table(components)

        self.annotated_a = self._annotate_peaks(self.peak_a, "A")
        self.annotated_b = self._annotate_peaks(self.peak_b, "B")

        shared_a = self.annotated_a.loc[
            self.annotated_a["overlap_status"] == "shared"
        ].copy()
        shared_b = self.annotated_b.loc[
            self.annotated_b["overlap_status"] == "shared"
        ].copy()
        self.shared_peaks = pd.concat([shared_a, shared_b], ignore_index=True, sort=False)
        if not self.shared_peaks.empty:
            self.shared_peaks = self.shared_peaks.sort_values(
                ["shared_cluster_id", "comparison_sample", "transcripts", "_match_start"],
                kind="stable",
            ).reset_index(drop=True)
        self.specific_a = self.annotated_a.loc[
            self.annotated_a["overlap_status"] == "specific"
        ].copy()
        self.specific_b = self.annotated_b.loc[
            self.annotated_b["overlap_status"] == "specific"
        ].copy()
        if not self.specific_a.empty:
            self.specific_a = self.specific_a.sort_values(
                ["transcripts", "_match_start", "_match_end"],
                kind="stable",
            ).reset_index(drop=True)
        if not self.specific_b.empty:
            self.specific_b = self.specific_b.sort_values(
                ["transcripts", "_match_start", "_match_end"],
                kind="stable",
            ).reset_index(drop=True)


    def result_counts(self) -> dict[str, int | float]:
        """Return concise overlap counts for CLI reporting."""
        shared_a = int(len(self.peak_a) - len(self.specific_a))
        shared_b = int(len(self.peak_b) - len(self.specific_b))
        qualifying_relationships = 0
        if not self.relationships.empty:
            qualifying_relationships = int(
                self.relationships["qualifying_overlap"].astype(bool).sum()
            )
        return {
            "sample_a_peaks": int(len(self.peak_a)),
            "sample_b_peaks": int(len(self.peak_b)),
            "sample_a_shared": shared_a,
            "sample_b_shared": shared_b,
            "sample_a_specific": int(len(self.specific_a)),
            "sample_b_specific": int(len(self.specific_b)),
            "shared_clusters": int(len(self.shared_clusters)),
            "qualifying_relationships": qualifying_relationships,
        }